// Aviso de error para Admin (privado). Todo texto variable se escapa (Telegram HTML).
const d = $input.first().json || {};
const ex = d.execution || {};
const wf = d.workflow || {};
const tr = d.trigger || {};
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const err = ex.error || tr.error || d.error || {};
let msg = String(err.message || err.description || 'Sin mensaje de error');
if (msg.length > 500) msg = msg.slice(0, 500) + '…';

const nodo = ex.lastNodeExecuted || 'desconocido';
const nombre = wf.name || 'sin nombre';
let texto = '⚠️ <b>Error en flujo: ' + esc(nombre) + '</b>\n'
  + 'Nodo: ' + esc(nodo) + '\n'
  + 'Mensaje: ' + esc(msg);
if (ex.id && wf.id) {
  const url = 'https://n8n.example.com/workflow/' + esc(wf.id) + '/executions/' + esc(ex.id);
  texto += '\n<a href="' + url + '">Ver ejecución</a>';
}
return [{ json: { aviso: texto } }];
